def odd_Equivalent(s, k):
    n = len(s)
    if n == 0 or k <= 0:
        return 0
    count = 0
    cur = s
    for _ in range(k):
        cur = cur[1:] + cur[0]
        if int(cur, 2) % 2 == 1:
            count += 1
    return count
```

